package com.primehr.succession.application;
import com.primehr.config.PrimeHrProperties;import com.primehr.integration.administrative.*;import com.primehr.integration.humanresource.*;import com.primehr.rsp.applicant.storage.DocumentStorage;import com.primehr.shared.audit.PrimeHrAuditService;import com.primehr.shared.exception.*;import com.primehr.succession.api.SuccessionIntakeDtos.*;import com.primehr.succession.domain.*;import com.primehr.succession.infrastructure.*;import org.springframework.security.access.AccessDeniedException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.multipart.MultipartFile;import java.io.*;import java.nio.file.Path;import java.security.*;import java.time.*;import java.util.*;

@Service @Transactional public class SuccessionIntakeServiceImpl implements SuccessionIntakeService{
 private static final ZoneId MANILA=ZoneId.of("Asia/Manila");private final SuccessionCycleRepository cycles;private final SuccessionContinuityRiskReviewRepository risks;private final SuccessionCandidateRepository candidates;private final SuccessionEligibilityFindingRepository findings;private final SuccessionCandidateEvidenceRepository evidence;private final SuccessionGovernancePolicyVersionRepository policies;private final SuccessionCommitteeCharterVersionRepository charters;private final SuccessionCommitteeMemberRepository members;private final SuccessionCriticalPositionDesignationRepository designations;private final HumanResourceAssessmentSubjectClient hr;private final AdministrativePositionTargetClient positions;private final DocumentStorage storage;private final PrimeHrProperties properties;private final PrimeHrAuditService audit;
 public SuccessionIntakeServiceImpl(SuccessionCycleRepository cycles,SuccessionContinuityRiskReviewRepository risks,SuccessionCandidateRepository candidates,SuccessionEligibilityFindingRepository findings,SuccessionCandidateEvidenceRepository evidence,SuccessionGovernancePolicyVersionRepository policies,SuccessionCommitteeCharterVersionRepository charters,SuccessionCommitteeMemberRepository members,SuccessionCriticalPositionDesignationRepository designations,HumanResourceAssessmentSubjectClient hr,AdministrativePositionTargetClient positions,DocumentStorage storage,PrimeHrProperties properties,PrimeHrAuditService audit){this.cycles=cycles;this.risks=risks;this.candidates=candidates;this.findings=findings;this.evidence=evidence;this.policies=policies;this.charters=charters;this.members=members;this.designations=designations;this.hr=hr;this.positions=positions;this.storage=storage;this.properties=properties;this.audit=audit;}
 @Override @Transactional(readOnly=true)public List<CycleResponse>cycles(String a){return cycles.findByAgencyIdOrderByCreatedAtDesc(a).stream().map(this::cycleResponse).toList();}
 @Override public CycleResponse createCycle(String a,CycleInput i,String c){newRecord(i.recordVersion());if(cycles.existsByAgencyIdAndNormalizedCode(a,i.code().trim().toUpperCase(Locale.ROOT)))throw new IllegalArgumentException("Succession cycle code already exists");var p=policy(a,i.policyVersionId());var ch=charter(a,i.charterVersionId());effective(p,i.nominationOpensOn(),"Succession policy");effective(ch,i.nominationOpensOn(),"Committee charter");var v=cycles.saveAndFlush(new SuccessionCycle(a,i.code(),i.title(),i.description(),p.getId(),p.getDefinitionVersion(),policyFingerprint(p),ch.getId(),i.nominationOpensOn(),i.nominationClosesOn(),i.eligibilityDueOn()));var out=cycleResponse(v);record(a,"CREATE_SUCCESSION_CYCLE","SUCCESSION_CYCLE",v,null,out,null,c);return out;}
 @Override public CycleResponse updateCycle(String a,String id,CycleInput i,String c){var v=cycle(a,id);check(v.getVersion(),i.recordVersion());if(!v.getCode().equalsIgnoreCase(i.code()))throw new IllegalArgumentException("Succession cycle code cannot change");var p=policy(a,i.policyVersionId());var ch=charter(a,i.charterVersionId());effective(p,i.nominationOpensOn(),"Succession policy");effective(ch,i.nominationOpensOn(),"Committee charter");var before=cycleResponse(v);v.update(i.title(),i.description(),p.getId(),p.getDefinitionVersion(),policyFingerprint(p),ch.getId(),i.nominationOpensOn(),i.nominationClosesOn(),i.eligibilityDueOn());cycles.saveAndFlush(v);var out=cycleResponse(v);record(a,"UPDATE_SUCCESSION_CYCLE","SUCCESSION_CYCLE",v,before,out,null,c);return out;}
 @Override public CycleResponse transitionCycle(String a,String id,Transition i,String action,String c){var v=cycle(a,id);check(v.getVersion(),i.recordVersion());var before=cycleResponse(v);if("open".equals(action)){effective(policy(a,v.getPolicyVersionId()),v.getNominationOpensOn(),"Succession policy");effective(charter(a,v.getCharterVersionId()),v.getNominationOpensOn(),"Committee charter");v.open(audit.currentActor(),i.reason(),Instant.now());}else if("close".equals(action))v.close(audit.currentActor(),i.reason(),Instant.now());else if("cancel".equals(action))v.cancel(audit.currentActor(),i.reason(),Instant.now());else throw new IllegalArgumentException("Unsupported cycle action");cycles.saveAndFlush(v);var out=cycleResponse(v);record(a,"SUCCESSION_CYCLE_"+action.toUpperCase(Locale.ROOT),"SUCCESSION_CYCLE",v,before,out,i.reason(),c);return out;}
 @Override @Transactional(readOnly=true)public List<RiskResponse>riskReviews(String a,String cycle,String actor,PermissionDataScope scope){var cy=cycle(a,cycle);assigned(a,cy,actor,scope);return risks.findByAgencyIdAndCycleIdOrderByCreatedAtDesc(a,cy.getId()).stream().map(this::riskResponse).toList();}
 @Override public RiskResponse createRiskReview(String a,String cycle,RiskInput i,String actor,PermissionDataScope scope,String c){newRecord(i.recordVersion());var cy=cycle(a,cycle);assigned(a,cy,actor,scope);var d=designation(a,i.designationId());approvedEffective(d,i.reviewDate());if(risks.existsByAgencyIdAndCycleIdAndDesignationId(a,cy.getId(),d.getId()))throw new IllegalArgumentException("This position already has a risk review in the cycle");var v=risks.saveAndFlush(new SuccessionContinuityRiskReview(a,cy.getId(),d,i.riskLevel(),i.riskReason(),i.continuityControls(),i.reviewDate(),i.nextReviewDate()));var out=riskResponse(v);record(a,"CREATE_SUCCESSION_RISK_REVIEW","SUCCESSION_RISK_REVIEW",v,null,out,null,c);return out;}
 @Override public RiskResponse updateRiskReview(String a,String id,RiskInput i,String actor,PermissionDataScope scope,String c){var v=risk(a,id);var cy=cycle(a,v.getCycleId());assigned(a,cy,actor,scope);check(v.getVersion(),i.recordVersion());if(!v.getDesignationId().equals(i.designationId()))throw new IllegalArgumentException("Critical-position designation cannot change");var before=riskResponse(v);v.update(i.riskLevel(),i.riskReason(),i.continuityControls(),i.reviewDate(),i.nextReviewDate());risks.saveAndFlush(v);var out=riskResponse(v);record(a,"UPDATE_SUCCESSION_RISK_REVIEW","SUCCESSION_RISK_REVIEW",v,before,out,null,c);return out;}
 @Override public RiskResponse finalizeRiskReview(String a,String id,Transition i,String actor,PermissionDataScope scope,String c){var v=risk(a,id);assigned(a,cycle(a,v.getCycleId()),actor,scope);check(v.getVersion(),i.recordVersion());var before=riskResponse(v);v.finalizeReview(actor,Instant.now());risks.saveAndFlush(v);var out=riskResponse(v);record(a,"FINALIZE_SUCCESSION_RISK_REVIEW","SUCCESSION_RISK_REVIEW",v,before,out,i.reason(),c);return out;}
 @Override @Transactional(readOnly=true)public List<CandidateResponse>candidates(String a,String actor,PermissionDataScope scope){return candidates.findByAgencyIdOrderByCreatedAtDesc(a).stream().filter(v->visible(a,v,actor,scope)).map(v->candidateResponse(a,v,actor,scope)).toList();}
 @Override @Transactional(readOnly=true)public CandidateResponse candidate(String a,String id,String actor,PermissionDataScope scope){var v=candidate(a,id);access(a,v,actor,scope);return candidateResponse(a,v,actor,scope);}
 @Override public CandidateResponse createCandidate(String a,CandidateInput i,String token,String actor,PermissionDataScope scope,String c){newRecord(i.recordVersion());var cy=cycle(a,i.cycleId());if(!cy.accepts(LocalDate.now(MANILA)))throw new IllegalStateException("Succession cycle is not accepting candidate intake today");var p=policy(a,cy.getPolicyVersionId());if(i.intakeType()==SuccessionCandidate.IntakeType.SELF_EXPRESSION_OF_INTEREST&&!p.isAllowsSelfExpression())throw new IllegalStateException("The effective succession policy does not allow self-expression of interest");var d=designation(a,i.designationId());approvedEffective(d,LocalDate.now(MANILA));var e=employee(i.employeeId(),token);if(i.intakeType()==SuccessionCandidate.IntakeType.SELF_EXPRESSION_OF_INTEREST&&!e.employeeNo().equalsIgnoreCase(actor))throw new AccessDeniedException("Self-expression of interest is limited to the authenticated employee");if(scope==PermissionDataScope.OWN_RECORDS&&!e.employeeNo().equalsIgnoreCase(actor))throw new AccessDeniedException("Own Records scope permits only the authenticated employee");if(scope==PermissionDataScope.ASSIGNED_RECORDS)assigned(a,cy,actor,scope);if(candidates.existsByAgencyIdAndCycleIdAndDesignationIdAndEmployeeId(a,cy.getId(),d.getId(),e.employeeId()))throw new IllegalArgumentException("The employee already has candidate intake for this position in the cycle");var v=candidates.saveAndFlush(new SuccessionCandidate(a,cy.getId(),d,i.intakeType(),actor,e,i.nominationReason()));var out=candidateResponse(a,v,actor,scope);record(a,"CREATE_SUCCESSION_CANDIDATE_INTAKE","SUCCESSION_CANDIDATE",v,null,out,null,c);return out;}
 @Override public CandidateResponse updateCandidate(String a,String id,CandidateInput i,String actor,PermissionDataScope scope,String c){var v=candidate(a,id);mutate(a,v,actor,scope);check(v.getVersion(),i.recordVersion());if(!v.getCycleId().equals(i.cycleId())||!v.getDesignationId().equals(i.designationId())||!v.getEmployeeId().equals(i.employeeId())||v.getIntakeType()!=i.intakeType())throw new IllegalArgumentException("Cycle, target, employee, and intake type are immutable");var before=candidateResponse(a,v,actor,scope);v.updateReason(i.nominationReason());candidates.saveAndFlush(v);var out=candidateResponse(a,v,actor,scope);record(a,"UPDATE_SUCCESSION_CANDIDATE_INTAKE","SUCCESSION_CANDIDATE",v,before,out,null,c);return out;}
 @Override public CandidateResponse sendNotice(String a,String id,NoticeInput i,String actor,PermissionDataScope scope,String c){var v=candidate(a,id);committeeAction(a,v,actor,scope);check(v.getVersion(),i.recordVersion());var before=candidateResponse(a,v,actor,scope);v.sendNotice(actor,i.noticeText(),Instant.now());candidates.saveAndFlush(v);var out=candidateResponse(a,v,actor,scope);record(a,"SEND_SUCCESSION_CANDIDATE_NOTICE","SUCCESSION_CANDIDATE",v,before,out,null,c);return out;}
 @Override public CandidateResponse consent(String a,String id,ConsentInput i,String actor,PermissionDataScope scope,String c){var v=candidate(a,id);access(a,v,actor,scope);check(v.getVersion(),i.recordVersion());if(!i.consent())throw new IllegalArgumentException("Affirmative consent is required; use withdrawal to decline");var before=candidateResponse(a,v,actor,scope);v.consent(actor,i.consentStatement(),Instant.now());candidates.saveAndFlush(v);var out=candidateResponse(a,v,actor,scope);record(a,"CONSENT_SUCCESSION_CANDIDATE","SUCCESSION_CANDIDATE",v,before,out,null,c);return out;}
 @Override public CandidateResponse submit(String a,String id,Transition i,String token,String actor,PermissionDataScope scope,String c){var v=candidate(a,id);mutate(a,v,actor,scope);check(v.getVersion(),i.recordVersion());var cy=cycle(a,v.getCycleId());if(!cy.accepts(LocalDate.now(MANILA)))throw new IllegalStateException("Succession cycle is not accepting candidate intake today");var e=employee(v.getEmployeeId(),token);if(!v.getAppointmentId().equals(e.appointmentId())||!v.getEmployeeFingerprint().equals(e.sourceFingerprint()))throw new OptimisticConflictException("Employee appointment changed; create refreshed candidate intake");var d=designation(a,v.getDesignationId());var target=positions.get(d.getTargetType(),d.getTargetId(),token);if(!v.getTargetFingerprint().equals(target.sourceFingerprint()))throw new OptimisticConflictException("Target position changed; create refreshed candidate intake");if(evidence.findByAgencyIdAndCandidateIdOrderByUploadedAtAsc(a,id).isEmpty())throw new IllegalStateException("At least one evidence file is required before submission");var before=candidateResponse(a,v,actor,scope);v.submit(actor,Instant.now());candidates.saveAndFlush(v);var out=candidateResponse(a,v,actor,scope);record(a,"SUBMIT_SUCCESSION_CANDIDATE","SUCCESSION_CANDIDATE",v,before,out,i.reason(),c);return out;}
 @Override public CandidateResponse decideEligibility(String a,String id,EligibilityInput i,String actor,PermissionDataScope scope,String c){var v=candidate(a,id);committeeAction(a,v,actor,scope);check(v.getVersion(),i.recordVersion());validateFindings(i);var before=candidateResponse(a,v,actor,scope);findings.deleteByAgencyIdAndCandidateId(a,id);findings.flush();findings.saveAll(i.findings().stream().map(x->new SuccessionEligibilityFinding(a,id,x.criterionCode(),x.criterionLabel(),x.outcome(),x.reason(),x.employeeVisible(),x.displayOrder())).toList());v.decideEligibility(i.eligible(),actor,i.reason(),Instant.now());candidates.saveAndFlush(v);var out=candidateResponse(a,v,actor,scope);record(a,"DECIDE_SUCCESSION_ELIGIBILITY","SUCCESSION_CANDIDATE",v,before,out,i.reason(),c);return out;}
 @Override public CandidateResponse withdraw(String a,String id,Transition i,String actor,PermissionDataScope scope,String c){var v=candidate(a,id);access(a,v,actor,scope);check(v.getVersion(),i.recordVersion());var before=candidateResponse(a,v,actor,scope);v.withdraw(actor,i.reason(),Instant.now());candidates.saveAndFlush(v);var out=candidateResponse(a,v,actor,scope);record(a,"WITHDRAW_SUCCESSION_CANDIDATE","SUCCESSION_CANDIDATE",v,before,out,i.reason(),c);return out;}
 @Override public EvidenceResponse upload(String a,String id,String title,SuccessionCandidateEvidence.Visibility visibility,String retention,MultipartFile file,String actor,PermissionDataScope scope,String c){var v=candidate(a,id);mutate(a,v,actor,scope);if(v.getStatus()!=SuccessionCandidate.Status.DRAFT&&v.getStatus()!=SuccessionCandidate.Status.NOTICE_SENT&&v.getStatus()!=SuccessionCandidate.Status.CONSENTED)throw new IllegalStateException("Evidence may only be added before submission");if(!properties.storage().enabled())throw new IllegalStateException("Document uploads are disabled");if(file==null||file.isEmpty()||file.getSize()>properties.storage().maximumBytes())throw new IllegalArgumentException("Evidence size is invalid");String media=Objects.requireNonNullElse(file.getContentType(),"");if(!properties.storage().allowedMediaTypes().contains(media))throw new IllegalArgumentException("Evidence media type is not allowed");byte[] bytes;try{bytes=file.getBytes();}catch(IOException e){throw new IllegalArgumentException("Evidence could not be read",e);}verifySignature(media,bytes);String filename=safeFilename(file.getOriginalFilename()),key=a+"/succession/"+id+"/"+UUID.randomUUID().toString().replace("-","");storage.put(key,bytes,media);try{var x=evidence.saveAndFlush(new SuccessionCandidateEvidence(a,id,title,filename,storage.provider(),key,media,bytes.length,sha(bytes),visibility,retention,actor,Instant.now()));var out=evidenceResponse(x);record(a,"UPLOAD_SUCCESSION_CANDIDATE_EVIDENCE","SUCCESSION_CANDIDATE_EVIDENCE",x,null,out,null,c);return out;}catch(RuntimeException ex){storage.delete(key);throw ex;}}
 @Override public EvidenceContent download(String a,String id,String evidenceId,String actor,PermissionDataScope scope,String c){var v=candidate(a,id);access(a,v,actor,scope);var x=evidence.findByIdAndAgencyIdAndCandidateId(evidenceId,a,id).orElseThrow(()->new ResourceNotFoundException("Candidate evidence not found"));if(x.getVisibility()==SuccessionCandidateEvidence.Visibility.COMMITTEE_RESTRICTED&&!privileged(a,v,actor,scope))throw new AccessDeniedException("Committee-restricted evidence is not available to the candidate");record(a,"DOWNLOAD_SUCCESSION_CANDIDATE_EVIDENCE","SUCCESSION_CANDIDATE_EVIDENCE",x,null,Map.of("requestedBy",actor),null,c);return new EvidenceContent(x.getOriginalFilename(),x.getMediaType(),x.getByteSize(),storage.get(x.getStorageObjectKey()));}
 private boolean visible(String a,SuccessionCandidate v,String actor,PermissionDataScope scope){return scope==PermissionDataScope.AGENCY_WIDE||v.getEmployeeNo().equalsIgnoreCase(actor)||v.getInitiatedBy().equalsIgnoreCase(actor)||scope==PermissionDataScope.ASSIGNED_RECORDS&&activeMember(a,cycle(a,v.getCycleId()).getCharterVersionId(),actor);}
 private void access(String a,SuccessionCandidate v,String actor,PermissionDataScope scope){if(!visible(a,v,actor,scope))throw new AccessDeniedException("Candidate intake is outside the permitted data scope");}
 private void mutate(String a,SuccessionCandidate v,String actor,PermissionDataScope scope){access(a,v,actor,scope);if(scope!=PermissionDataScope.AGENCY_WIDE&&!v.getInitiatedBy().equalsIgnoreCase(actor)&&!v.getEmployeeNo().equalsIgnoreCase(actor))throw new AccessDeniedException("Candidate intake cannot be changed by this user");}
 private void committeeAction(String a,SuccessionCandidate v,String actor,PermissionDataScope scope){assigned(a,cycle(a,v.getCycleId()),actor,scope);if(v.getEmployeeNo().equalsIgnoreCase(actor))throw new AccessDeniedException("Candidate cannot perform committee action on their own intake");}
 private void assigned(String a,SuccessionCycle cycle,String actor,PermissionDataScope scope){if(scope==PermissionDataScope.AGENCY_WIDE)return;if(scope!=PermissionDataScope.ASSIGNED_RECORDS||!activeMember(a,cycle.getCharterVersionId(),actor))throw new AccessDeniedException("Cycle is not assigned to the current committee member");}
 private boolean activeMember(String a,String charter,String actor){LocalDate on=LocalDate.now(MANILA);return members.findByAgencyIdAndCharterVersionIdOrderByMemberRole(a,charter).stream().anyMatch(m->m.getEmployeeNo().equalsIgnoreCase(actor)&&!on.isBefore(m.getEffectiveFrom())&&(m.getEffectiveTo()==null||!on.isAfter(m.getEffectiveTo())));}
 private boolean privileged(String a,SuccessionCandidate v,String actor,PermissionDataScope scope){return scope==PermissionDataScope.AGENCY_WIDE||scope==PermissionDataScope.ASSIGNED_RECORDS&&activeMember(a,cycle(a,v.getCycleId()).getCharterVersionId(),actor);}
 private CandidateResponse candidateResponse(String a,SuccessionCandidate v,String actor,PermissionDataScope scope){boolean privileged=privileged(a,v,actor,scope);var fs=findings.findByAgencyIdAndCandidateIdOrderByDisplayOrder(a,v.getId()).stream().filter(x->privileged||x.isEmployeeVisible()).map(x->new FindingResponse(x.getId(),x.getCriterionCode(),x.getCriterionLabel(),x.getOutcome().name(),x.getReason(),x.isEmployeeVisible(),x.getDisplayOrder())).toList();var es=evidence.findByAgencyIdAndCandidateIdOrderByUploadedAtAsc(a,v.getId()).stream().filter(x->privileged||x.getVisibility()==SuccessionCandidateEvidence.Visibility.CANDIDATE_VISIBLE).map(this::evidenceResponse).toList();return new CandidateResponse(v.getId(),v.getCycleId(),v.getDesignationId(),v.getIntakeType().name(),v.getInitiatedBy(),v.getEmployeeId(),v.getEmployeeNo(),v.getEmployeeName(),v.getAppointmentId(),v.getCurrentJobPositionId(),v.getCurrentPlantillaId(),v.getTargetType(),v.getTargetId(),v.getTargetJobPositionId(),v.getTargetPositionName(),v.getTargetPlantillaId(),v.getTargetPlantillaName(),v.getNominationReason(),v.getStatus().name(),v.getNoticeText(),v.getNoticeSentAt(),v.getConsentStatement(),v.getConsentedAt(),v.getEligibilityOutcome(),v.getEligibilityReason(),v.getEligibilityReviewedBy(),v.getEligibilityReviewedAt(),v.getWithdrawnBy(),v.getWithdrawnAt(),v.getWithdrawalReason(),v.getVersion(),fs,es);}
 private static void validateFindings(EligibilityInput i){Set<String>codes=new HashSet<>();Set<Integer>orders=new HashSet<>();for(var x:i.findings())if(!codes.add(x.criterionCode().trim().toUpperCase(Locale.ROOT))||!orders.add(x.displayOrder()))throw new IllegalArgumentException("Eligibility criteria and display order must be unique");if(i.eligible()&&i.findings().stream().anyMatch(x->x.outcome()!=SuccessionEligibilityFinding.Outcome.MET))throw new IllegalArgumentException("Eligible outcome requires all criteria to be met");}
 private HumanResourceAssessmentSubject employee(Long id,String token){var x=hr.get(id,token);if(x.appointmentId()==null||x.employeeNo()==null||x.sourceFingerprint()==null)throw new IllegalStateException("Employee requires an active authoritative appointment snapshot");return x;}
 private static void approvedEffective(SuccessionCriticalPositionDesignation d,LocalDate on){if(d.getStatus()!=SuccessionCriticalPositionDesignation.Status.APPROVED||d.getEffectiveFrom()==null||on.isBefore(d.getEffectiveFrom())||d.getEffectiveTo()!=null&&on.isAfter(d.getEffectiveTo()))throw new IllegalStateException("Critical-position designation must be approved and effective");}
 private static void effective(SuccessionVersionedDefinition v,LocalDate on,String label){if(!v.effectiveOn(on))throw new IllegalStateException(label+" must be published and effective when nominations open");}
 private CycleResponse cycleResponse(SuccessionCycle x){return new CycleResponse(x.getId(),x.getCode(),x.getTitle(),x.getDescription(),x.getPolicyVersionId(),x.getPolicyDefinitionVersion(),x.getCharterVersionId(),x.getNominationOpensOn(),x.getNominationClosesOn(),x.getEligibilityDueOn(),x.getStatus().name(),x.getVersion());}
 private RiskResponse riskResponse(SuccessionContinuityRiskReview x){return new RiskResponse(x.getId(),x.getCycleId(),x.getDesignationId(),x.getTargetType(),x.getTargetId(),x.getJobPositionId(),x.getPositionName(),x.getPlantillaId(),x.getPlantillaName(),x.getRiskLevel().name(),x.getRiskReason(),x.getContinuityControls(),x.getReviewDate(),x.getNextReviewDate(),x.getStatus().name(),x.getFinalizedBy(),x.getFinalizedAt(),x.getVersion());}
 private EvidenceResponse evidenceResponse(SuccessionCandidateEvidence x){return new EvidenceResponse(x.getId(),x.getTitle(),x.getOriginalFilename(),x.getMediaType(),x.getByteSize(),x.getChecksum(),x.getVisibility().name(),x.getRetentionTag(),x.getUploadedBy(),x.getUploadedAt());}
 private SuccessionCycle cycle(String a,String id){return cycles.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Succession cycle not found"));}private SuccessionContinuityRiskReview risk(String a,String id){return risks.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Continuity risk review not found"));}private SuccessionCandidate candidate(String a,String id){return candidates.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Succession candidate intake not found"));}private SuccessionGovernancePolicyVersion policy(String a,String id){return policies.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Succession policy version not found"));}private SuccessionCommitteeCharterVersion charter(String a,String id){return charters.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Succession committee charter not found"));}private SuccessionCriticalPositionDesignation designation(String a,String id){return designations.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Critical-position designation not found"));}
 private static String policyFingerprint(SuccessionGovernancePolicyVersion x){return x.getId()+":"+x.getDefinitionVersion()+":"+x.getVersion();}private static void newRecord(Long v){if(v!=null)throw new IllegalArgumentException("recordVersion must be omitted for new records");}private static void check(long actual,Long expected){if(expected==null||actual!=expected)throw new OptimisticConflictException("Record changed; reload and retry");}
 private void record(String a,String action,String type,com.primehr.rsp.domain.RspAuditedEntity v,Object before,Object after,String reason,String c){audit.record(a,action,type,v.getId(),null,v.getVersion(),before,after,reason,c);}private static String safeFilename(String value){String n=value==null?"evidence":Path.of(value).getFileName().toString();return n.replaceAll("[^A-Za-z0-9._ -]","_");}private static String sha(byte[] b){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}private static void verifySignature(String media,byte[] b){boolean ok=switch(media){case"application/pdf"->b.length>4&&b[0]=='%'&&b[1]=='P'&&b[2]=='D'&&b[3]=='F';case"image/png"->b.length>8&&(b[0]&255)==137&&b[1]=='P'&&b[2]=='N'&&b[3]=='G';case"image/jpeg"->b.length>3&&(b[0]&255)==255&&(b[1]&255)==216&&(b[2]&255)==255;default->false;};if(!ok)throw new IllegalArgumentException("Evidence content does not match its media type");}
}
